Q: Best design for request handling with DTOs that have a type field that defines the behaviour of an endpoint A: <p>you can use this code for better efficency and problem of null pointer</p>
<pre><code>public interface PaymentProcessor {
    void process(GenericPaymentRequestDTO request);
    void populateLog(GenericPaymentRequestDTO request, PaymentLog log);
}

@Service
public class PaymentXProcessor implements PaymentProcessor {
    @Override
    public void process(GenericPaymentRequestDTO request) {
        // business logic for type X
    }

    @Override
    public void populateLog(GenericPaymentRequestDTO request, PaymentLog log) {
        log.setUser(userRepository.findById(request.getUserId()).orElseThrow(...));
        log.setCoupon(couponRepository.findById(request.getCouponId()).orElseThrow(...));
    }
}


