@Transactional
public void processGenericPayment(GenericPaymentRequestDTO request) {
    User manager = userRepository.findById(request.getManagerId()).orElseThrow(...);
    if (!userService.checkAdminAccess(manager.getEmail())) {
        throw new AccessDeniedException(&quot;Not allowed&quot;);
    }

    PaymentProcessor processor = processorMap.get(request.getType());
    if (processor == null) throw new IllegalArgumentException(&quot;Unsupported type&quot;);

    processor.process(request);

    PaymentLog log = new PaymentLog();
    log.setManager(manager);
    log.setType(request.getType());
    log.setPrice(request.getPrice());
    log.setDate(LocalDateTime.now());
    log.setMessage(request.getMessage());

    processor.populateLog(request, log);

    logRepository.save(log);
}



